   areas=["Model Town","Sector 1","Sector 2","Sector 3","Sector 14","Shivaji Colony","Subhash Nagar","Prem Nagar","Jhang Colony","MDU campus area","PGIMS area","IMT Rohtak","Sampla","Meham"],
